import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import { LayoutDashboard, List, Inbox, Plus, Eye, Edit, Trash2, Phone, Mail, Calendar } from 'lucide-react';
import { useAuth } from '../../context/AuthContext';
import { MOCK_PROPERTIES, MOCK_VIEWING_REQUESTS, formatPrice, STATUS_LABELS, REQUEST_STATUS_LABELS } from '../../data/mockData';
import './AgentDashboard.css';

const TABS = [
  { id: 'overview', label: 'Overview', icon: <LayoutDashboard size={16} /> },
  { id: 'listings', label: 'My Listings', icon: <List size={16} /> },
  { id: 'requests', label: 'Viewing Requests', icon: <Inbox size={16} /> },
];

export default function AgentDashboard() {
  const { user } = useAuth();
  const [tab, setTab] = useState('overview');

  const myListings = MOCK_PROPERTIES.filter(p => p.agentId === (user?.agentId || 1));
  const myRequests = MOCK_VIEWING_REQUESTS.filter(r =>
    myListings.some(l => l.id === r.propertyId)
  );

  const stats = [
    { label: 'Active Listings', value: myListings.filter(p => p.status === 'available').length, color: '#e0f2fe', iconColor: '#0284c7' },
    { label: 'Total Views', value: myListings.reduce((s, p) => s + p.views, 0), color: '#dcfce7', iconColor: '#16a34a' },
    { label: 'Pending Requests', value: myRequests.filter(r => r.status === 'pending').length, color: '#fef3c7', iconColor: '#d97706' },
    { label: 'Completed Viewings', value: myRequests.filter(r => r.status === 'completed').length, color: '#f3e8ff', iconColor: '#9333ea' },
  ];

  return (
    <div className="dashboard">
      <div className="dashboard-sidebar">
        <div className="sidebar-profile">
          <div className="sidebar-avatar">{user?.name?.charAt(0)}</div>
          <div>
            <div className="sidebar-name">{user?.name}</div>
            <div className="sidebar-role">Property Agent</div>
          </div>
        </div>
        <nav className="sidebar-nav">
          {TABS.map(t => (
            <button key={t.id} className={`sidebar-link ${tab === t.id ? 'active' : ''}`} onClick={() => setTab(t.id)}>
              {t.icon} {t.label}
              {t.id === 'requests' && myRequests.filter(r => r.status === 'pending').length > 0 && (
                <span className="nav-badge">{myRequests.filter(r => r.status === 'pending').length}</span>
              )}
            </button>
          ))}
        </nav>
      </div>

      <div className="dashboard-content">
        {tab === 'overview' && (
          <div>
            <div className="dash-header">
              <h1>Welcome back, {user?.name?.split(' ')[0]}</h1>
              <p>Here's a summary of your listings and activity</p>
            </div>
            <div className="grid-4" style={{ marginBottom: '2rem' }}>
              {stats.map(s => (
                <div key={s.label} className="stat-card">
                  <div className="stat-icon" style={{ background: s.color, color: s.iconColor }}>
                    <LayoutDashboard size={22} />
                  </div>
                  <div>
                    <div className="stat-value">{s.value}</div>
                    <div className="stat-label">{s.label}</div>
                  </div>
                </div>
              ))}
            </div>

            <div className="grid-2">
              <div className="card" style={{ padding: '1.5rem' }}>
                <div className="card-section-header">
                  <h3>Recent Listings</h3>
                  <button className="btn btn-ghost btn-sm" onClick={() => setTab('listings')}>View All</button>
                </div>
                <div className="recent-list">
                  {myListings.slice(0, 3).map(p => {
                    const s = STATUS_LABELS[p.status];
                    return (
                      <div key={p.id} className="recent-item">
                        <img src={p.images[0]} alt={p.title} className="recent-thumb" />
                        <div className="recent-info">
                          <div className="recent-title">{p.title}</div>
                          <div className="recent-meta">{formatPrice(p.price, p.listingType)} · <Eye size={12} /> {p.views}</div>
                        </div>
                        <span className={`badge ${s.cls}`}>{s.label}</span>
                      </div>
                    );
                  })}
                </div>
              </div>

              <div className="card" style={{ padding: '1.5rem' }}>
                <div className="card-section-header">
                  <h3>Recent Requests</h3>
                  <button className="btn btn-ghost btn-sm" onClick={() => setTab('requests')}>View All</button>
                </div>
                <div className="recent-list">
                  {myRequests.slice(0, 3).map(r => {
                    const s = REQUEST_STATUS_LABELS[r.status];
                    return (
                      <div key={r.id} className="recent-item">
                        <div className="request-avatar">{r.clientName.charAt(0)}</div>
                        <div className="recent-info">
                          <div className="recent-title">{r.clientName}</div>
                          <div className="recent-meta">{r.propertyTitle}</div>
                        </div>
                        <span className={`badge ${s.cls}`}>{s.label}</span>
                      </div>
                    );
                  })}
                </div>
              </div>
            </div>
          </div>
        )}

        {tab === 'listings' && (
          <div>
            <div className="dash-header">
              <div>
                <h1>My Listings</h1>
                <p>Manage your property listings</p>
              </div>
              <button className="btn btn-primary"><Plus size={16} /> New Listing</button>
            </div>
            <div className="card">
              <div className="table-wrapper">
                <table>
                  <thead>
                    <tr>
                      <th>Property</th>
                      <th>Type</th>
                      <th>Price</th>
                      <th>Views</th>
                      <th>Status</th>
                      <th>Actions</th>
                    </tr>
                  </thead>
                  <tbody>
                    {myListings.map(p => {
                      const s = STATUS_LABELS[p.status];
                      return (
                        <tr key={p.id}>
                          <td>
                            <div className="table-property">
                              <img src={p.images[0]} alt="" className="table-thumb" />
                              <div>
                                <div className="table-title">{p.title}</div>
                                <div className="table-sub">{p.suburb}, {p.city}</div>
                              </div>
                            </div>
                          </td>
                          <td style={{ textTransform: 'capitalize' }}>{p.type}</td>
                          <td>{formatPrice(p.price, p.listingType)}</td>
                          <td><Eye size={14} style={{ marginRight: 4 }} />{p.views}</td>
                          <td><span className={`badge ${s.cls}`}>{s.label}</span></td>
                          <td>
                            <div className="table-actions">
                              <Link to={`/listings/${p.id}`} className="btn btn-ghost btn-sm"><Eye size={14} /></Link>
                              <button className="btn btn-ghost btn-sm"><Edit size={14} /></button>
                              <button className="btn btn-ghost btn-sm" style={{ color: 'var(--danger)' }}><Trash2 size={14} /></button>
                            </div>
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        )}

        {tab === 'requests' && (
          <div>
            <div className="dash-header">
              <div>
                <h1>Viewing Requests</h1>
                <p>Manage and respond to client viewing requests</p>
              </div>
            </div>
            <div className="requests-list">
              {myRequests.length === 0 ? (
                <div className="empty-state"><Inbox size={48} /><h3>No viewing requests yet</h3></div>
              ) : myRequests.map(r => {
                const s = REQUEST_STATUS_LABELS[r.status];
                return (
                  <div key={r.id} className="card request-card">
                    <div className="request-card-header">
                      <div className="request-client">
                        <div className="request-avatar">{r.clientName.charAt(0)}</div>
                        <div>
                          <div className="request-client-name">{r.clientName}</div>
                          <div className="request-property">{r.propertyTitle}</div>
                        </div>
                      </div>
                      <span className={`badge ${s.cls}`}>{s.label}</span>
                    </div>
                    <div className="request-details">
                      <span><Calendar size={14} /> {r.preferredDate} at {r.preferredTime}</span>
                      <a href={`tel:${r.clientPhone}`}><Phone size={14} /> {r.clientPhone}</a>
                      <a href={`mailto:${r.clientEmail}`}><Mail size={14} /> {r.clientEmail}</a>
                    </div>
                    {r.message && <p className="request-message">"{r.message}"</p>}
                    <div className="request-actions">
                      {r.status === 'pending' && (
                        <>
                          <button className="btn btn-primary btn-sm">Confirm</button>
                          <button className="btn btn-ghost btn-sm">Cancel</button>
                        </>
                      )}
                      {r.status === 'confirmed' && (
                        <button className="btn btn-accent btn-sm">Mark Completed</button>
                      )}
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
